BEGIN;

SET LOCAL standard_conforming_strings = on;

SET LOCAL TIME ZONE 'UTC';

CREATE TABLE public.products (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    estilo TEXT NOT NULL,
    color TEXT,
    acabado TEXT,
    marca TEXT,
    temporada TEXT,
    proveedor TEXT,
    sublinea TEXT,
    clasificacion TEXT,
    linea TEXT,
    imagen TEXT,
    ficha_imagen TEXT,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
  , codigo_barras TEXT, precio double precision DEFAULT 0, costo double precision DEFAULT 0, imagen_thumbnail TEXT, departamento TEXT DEFAULT 'ropa', observaciones TEXT, suela TEXT DEFAULT 'SUELAS', plantilla TEXT DEFAULT 'PLANTILLAS', tacon TEXT DEFAULT 'PISO', forro TEXT DEFAULT 'FORRO', catalogo TEXT, activo INTEGER DEFAULT 1, descripcion TEXT, corrida TEXT, estado TEXT, fecha_alta TEXT, comprador TEXT DEFAULT 'Sin asignar', pagina INTEGER DEFAULT 0, status INTEGER DEFAULT 1);

ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;


SELECT setval(pg_get_serial_sequence('public.products', 'id'), 362, true);

CREATE TABLE public.settings (
    key TEXT PRIMARY KEY,
    value TEXT,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
  );

ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY;

CREATE TABLE public.product_size_inventory (
    product_id bigint NOT NULL REFERENCES public.products(id),
    size TEXT NOT NULL,
    quantity INTEGER NOT NULL CHECK (quantity >= 0),
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (product_id, size)
  );

ALTER TABLE public.product_size_inventory ENABLE ROW LEVEL SECURITY;


CREATE TABLE public.inventory_movements (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id bigint NOT NULL REFERENCES public.products(id),
    size TEXT NOT NULL,
    operation TEXT NOT NULL CHECK (operation IN ('add', 'set')),
    previous_quantity INTEGER NOT NULL,
    quantity INTEGER NOT NULL,
    new_quantity INTEGER NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
  );

ALTER TABLE public.inventory_movements ENABLE ROW LEVEL SECURITY;


SELECT setval(pg_get_serial_sequence('public.inventory_movements', 'id'), 388, true);


CREATE FUNCTION public.claremm_require_catalog_fields() RETURNS trigger
LANGUAGE plpgsql SET search_path = '' AS $claremm$
BEGIN
  IF NULLIF(BTRIM(NEW.corrida), '') IS NULL
    OR NULLIF(BTRIM(NEW.catalogo), '') IS NULL
    OR NULLIF(BTRIM(NEW.linea), '') IS NULL THEN
    RAISE EXCEPTION 'Corrida, Catalogo y Linea son obligatorios.';
  END IF;
  RETURN NEW;
END;
$claremm$;
CREATE TRIGGER products_require_catalog_fields_insert
BEFORE INSERT ON public.products
FOR EACH ROW EXECUTE FUNCTION public.claremm_require_catalog_fields();
CREATE TRIGGER products_require_catalog_fields_update
BEFORE UPDATE OF corrida, catalogo, linea ON public.products
FOR EACH ROW EXECUTE FUNCTION public.claremm_require_catalog_fields();
COMMIT;
